/**
 * @file  usbd_conf.h
 * @brief Configuration of the ST USB device library (third_party/st_usb) for
 *        the ACwing FC firmware: one CDC interface, static memory, no LPM.
 *        Written by hand after the ST template (not generated by CubeMX).
 */
#ifndef USBD_CONF_H
#define USBD_CONF_H

#include "stm32wbxx.h"
#include "stm32wbxx_hal.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define USBD_MAX_NUM_INTERFACES       2U      /* CDC: communication + data */
#define USBD_MAX_NUM_CONFIGURATION    1U
#define USBD_MAX_STR_DESC_SIZ         128U
#define USBD_DEBUG_LEVEL              0U
#define USBD_LPM_ENABLED              0U
#define USBD_SELF_POWERED             1U
#define USBD_MAX_POWER                0x32U   /* 100 mA */

#define DEVICE_FS                     0

/* static allocation of the class data (no heap) */
void *USBD_static_malloc(uint32_t size);
void  USBD_static_free(void *p);
#define USBD_malloc     USBD_static_malloc
#define USBD_free       USBD_static_free
#define USBD_memset     memset
#define USBD_memcpy     memcpy
#define USBD_Delay      HAL_Delay

#define USBD_UsrLog(...)   do { } while (0)
#define USBD_ErrLog(...)   do { } while (0)
#define USBD_DbgLog(...)   do { } while (0)

#endif /* USBD_CONF_H */
